let cancionAbierta = ""; 
 
function mostrarCancion(nombre){ 
 
    if(cancionAbierta === nombre){ 
 
        document.getElementById("titulo").innerHTML = 
        "Selecciona una canción"; 
 
        document.getElementById("letra").innerHTML = 
        ""; 
 
        document.getElementById("audio").src = ""; 
 
        cancionAbierta = ""; 
 
        return; 
    } 
 
    let cancion = canciones[nombre]; 
 
    if(!cancion){ 
        document.getElementById("titulo").innerHTML = 
        "Próximamente"; 
 
        return; 
    } 
 
    cancionAbierta = nombre; 
 
    document.getElementById("titulo").innerHTML = 
    cancion.titulo; 
 
    document.getElementById("letra").innerHTML = 
    cancion.letra; 
 
    const audio = document.getElementById("audio"); 
 
audio.src = cancion.audio;
audio.load();
audio.play();

precargarSiguiente();

    audio.onended = function () {

    const botones = Array.from(
        document.querySelectorAll('button[onclick*="mostrarCancion"]')
    );

    let indiceActual = -1;

    for (let i = 0; i < botones.length; i++) {

        const texto = botones[i].getAttribute("onclick");

        if (texto.includes("'" + cancionAbierta + "'")) {
            indiceActual = i;
            break;
        }
    }

if (indiceActual >= 0 && indiceActual < botones.length - 1) {
    botones[indiceActual + 1].click();
    document.getElementById("audio").play();
}
};
}

function obtenerBotonesCanciones() {

    return Array.from(
        document.querySelectorAll('button[onclick*="mostrarCancion"]')
    );

}


function obtenerIndiceActual() {

    const botones = obtenerBotonesCanciones();

    for (let i = 0; i < botones.length; i++) {

        const texto = botones[i].getAttribute("onclick");

        if (texto.includes("'" + cancionAbierta + "'")) {
            return i;
        }

    }

    return -1;
}


function cancionSiguiente() {

    const botones = obtenerBotonesCanciones();
    const indice = obtenerIndiceActual();

    if (indice >= 0 && indice < botones.length - 1) {

        botones[indice + 1].click();

    }

}


function cancionAnterior() {

    const botones = obtenerBotonesCanciones();
    const indice = obtenerIndiceActual();

    if (indice > 0) {

        botones[indice - 1].click();

    }

}

let audioPrecarga = new Audio();

function precargarSiguiente() {

    const botones = Array.from(
        document.querySelectorAll('button[onclick*="mostrarCancion"]')
    );

    let indiceActual = -1;

    for (let i = 0; i < botones.length; i++) {

        const texto = botones[i].getAttribute("onclick");

        if (texto.includes("'" + cancionAbierta + "'")) {
            indiceActual = i;
            break;
        }
    }

    if (indiceActual >= 0 && indiceActual < botones.length - 1) {

        const textoSiguiente =
        botones[indiceActual + 1].getAttribute("onclick");

        const coincidencia =
        textoSiguiente.match(
            /mostrarCancion\(\s*['"](.+?)['"]\s*\)/
        );

        if (coincidencia) {

            const siguiente = canciones[coincidencia[1]];

            if (siguiente) {

                audioPrecarga.src = siguiente.audio;
                audioPrecarga.preload = "auto";

            }
        }
    }
}

// Lista de artistas
let artistas = [
    "Melanie Martinez",
    "Soda Stereo",
    "My Chemical Romance",
    "Latin Mafia",
    "Tito Double P",
    "Fuerza Regida"    
];

function buscarArtista(){

let texto = document
    .getElementById("buscarArtista")
    .value
    .toLowerCase()
    .trim();


    let artistas = {
        "melanie martinez": "MELANIE MARTINEZ.html",
        "melanie": "MELANIE MARTINEZ.html",
        "soda stereo": "Soda Stereo.html",
        "soda":"Soda Stereo.html",
        "my chemical romance": "My Chemical Romance.html",
        "my chemical": "My Chemical Romance.html",
        "latin mafia": "Latin Mafia.html",
        "latin": "Latin Mafia.html",
        "tito double p": "Tito Double P.html",
        "tito": "Tito Double P.html",
"fuerza regida": "Fuerza Regida.html",
"fuerza": "Fuerza Regida.html"
    };

console.log("Texto:", texto);
console.log("Resultado:", artistas[texto]);
    if(artistas[texto]){

        window.location.href = artistas[texto];

        document.getElementById("buscarArtista").value = "";
        document.getElementById("listaSugerencias").innerHTML = "";

    } else {

        alert("Artista no encontrado");

    }

}

function sugerenciasArtistas(){

    let texto = document.getElementById("buscarArtista").value.toLowerCase();

    let lista = document.getElementById("listaSugerencias");

    lista.innerHTML = "";

    if(texto === ""){
        return;
    }


let encontrado = false;


artistas.forEach(nombre => {

    if(nombre.toLowerCase().startsWith(texto)){

        encontrado = true;

        let opcion = document.createElement("div");

        opcion.innerHTML = nombre;

        opcion.onclick = function(){

            document.getElementById("buscarArtista").value = nombre;

            buscarArtista();

        };

        lista.appendChild(opcion);

    }

});


if(!encontrado){

    let opcion = document.createElement("div");

    opcion.innerHTML = "❌ Artista no encontrado";

    opcion.style.color = "pink";

    lista.appendChild(opcion);

}

}

function enterBuscar(event){

    if(event.key === "Enter"){

        buscarArtista();

    }

}

function toggleMenu(){
    const menu = document.getElementById("menuDesplegable");

    if(menu.style.display === "block"){
        menu.style.display = "none";
    }else{
        menu.style.display = "block";
    }
}

window.onclick = function(event){

    if(!event.target.matches('.menu-btn')){

        const menu = document.getElementById("menuDesplegable");

        if(menu.style.display === "block"){
            menu.style.display = "none";
        }

    }

}

const botonModo = document.getElementById("modo");

// Revisar si ya había elegido un modo
if(localStorage.getItem("tema") === "claro"){
    document.body.classList.add("claro");
    botonModo.textContent = "🌙";
}


botonModo.onclick = function(){

    document.body.classList.toggle("claro");

    if(document.body.classList.contains("claro")){

        localStorage.setItem("tema", "claro");
        botonModo.textContent = "🌙";

    }else{

        localStorage.setItem("tema", "oscuro");
        botonModo.textContent = "☀️";

    }

};
